#[test]
fn equation_rhocalc_quotedrop() {
    let _lang = RhoCalcLanguage;
    let meta = _lang.metadata();
    let equations = meta.equations();
    // Verify equation QuoteDrop (index 0) exists in metadata
    assert!(
        equations.len() > 0,
        "Expected at least 1 equations in metadata, found {}",
        equations.len()
    );
    let eq = &equations[0];
    assert!(!eq.lhs.is_empty(), "Equation QuoteDrop LHS should be non-empty");
    assert!(!eq.rhs.is_empty(), "Equation QuoteDrop RHS should be non-empty");
}

